-- Local-only owner stop markers; no restoration/deletion or administrative tamper-proof guarantee.
CREATE TABLE IF NOT EXISTS article_publication_stops(content_id TEXT NOT NULL PRIMARY KEY REFERENCES article_publications(content_id),owner_account_id TEXT REFERENCES private_accounts(id) ON DELETE SET NULL,source_version INTEGER NOT NULL CHECK(source_version BETWEEN 1 AND 9007199254740991),stopped_at_ms INTEGER NOT NULL CHECK(stopped_at_ms BETWEEN 0 AND 253402300799999));
CREATE TRIGGER IF NOT EXISTS article_publication_stops_valid BEFORE INSERT ON article_publication_stops BEGIN SELECT CASE WHEN NEW.owner_account_id IS NULL OR NOT EXISTS(SELECT 1 FROM article_publications r JOIN content c ON c.id=r.content_id JOIN private_accounts a ON a.id=r.owner_account_id AND a.status='active' WHERE r.content_id=NEW.content_id AND r.owner_account_id=NEW.owner_account_id AND r.source_version=NEW.source_version AND r.published_at_ms<=NEW.stopped_at_ms AND c.status='published' AND c.kind='article' AND c.is_sample=0 AND c.author_id=r.public_profile_id) THEN RAISE(ABORT,'publication stop unavailable') END; END;
CREATE TRIGGER IF NOT EXISTS article_publication_stops_apply AFTER INSERT ON article_publication_stops BEGIN UPDATE content SET status='hidden' WHERE id=NEW.content_id AND status='published' AND kind='article' AND is_sample=0; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'publication stop unavailable') END; END;
CREATE TRIGGER IF NOT EXISTS article_publication_stops_no_republish_insert BEFORE INSERT ON content WHEN NEW.status='published' AND EXISTS(SELECT 1 FROM article_publication_stops WHERE content_id=NEW.id) BEGIN SELECT RAISE(ABORT,'publication stop unavailable'); END;
CREATE TRIGGER IF NOT EXISTS article_publication_stops_no_republish_update BEFORE UPDATE OF status ON content WHEN NEW.status='published' AND EXISTS(SELECT 1 FROM article_publication_stops WHERE content_id=NEW.id) BEGIN SELECT RAISE(ABORT,'publication stop unavailable'); END;
CREATE TABLE IF NOT EXISTS project_publication_stops(project_id TEXT NOT NULL PRIMARY KEY REFERENCES project_publications(id),owner_account_id TEXT REFERENCES private_accounts(id) ON DELETE SET NULL,source_version INTEGER NOT NULL CHECK(source_version BETWEEN 1 AND 9007199254740991),stopped_at_ms INTEGER NOT NULL CHECK(stopped_at_ms BETWEEN 0 AND 253402300799999));
CREATE TRIGGER IF NOT EXISTS project_publication_stops_valid BEFORE INSERT ON project_publication_stops BEGIN SELECT CASE WHEN NEW.owner_account_id IS NULL OR NOT EXISTS(SELECT 1 FROM project_publications r JOIN private_accounts a ON a.id=r.owner_account_id AND a.status='active' WHERE r.id=NEW.project_id AND r.owner_account_id=NEW.owner_account_id AND r.source_version=NEW.source_version AND r.published_at_ms<=NEW.stopped_at_ms AND r.status='published') THEN RAISE(ABORT,'publication stop unavailable') END; END;
CREATE TRIGGER IF NOT EXISTS project_publication_stops_apply AFTER INSERT ON project_publication_stops BEGIN UPDATE project_publications SET status='hidden' WHERE id=NEW.project_id AND status='published'; SELECT CASE WHEN changes()!=1 THEN RAISE(ABORT,'publication stop unavailable') END; END;
CREATE TRIGGER IF NOT EXISTS project_publication_stops_no_republish_insert BEFORE INSERT ON project_publications WHEN NEW.status='published' AND EXISTS(SELECT 1 FROM project_publication_stops WHERE project_id=NEW.id) BEGIN SELECT RAISE(ABORT,'publication stop unavailable'); END;
CREATE TRIGGER IF NOT EXISTS project_publication_stops_no_republish_update BEFORE UPDATE OF status ON project_publications WHEN NEW.status='published' AND EXISTS(SELECT 1 FROM project_publication_stops WHERE project_id=NEW.id) BEGIN SELECT RAISE(ABORT,'publication stop unavailable'); END;
